package com.ebuddy.service;
import com.ebuddy.domain.*; import com.ebuddy.repo.*; import com.ebuddy.security.JwtService; import com.ebuddy.web.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.*; import java.util.*;
@Service public class AuthService { private final UserRepository users; private final SessionRepository sessions; private final PasswordEncoder encoder; private final JwtService jwt; private final StringRedisTemplate redis; public AuthService(UserRepository u,SessionRepository s,PasswordEncoder e,JwtService j,StringRedisTemplate r){users=u;sessions=s;encoder=e;jwt=j;redis=r;}
 @Transactional public ApiModels.LoginResponse login(ApiModels.LoginRequest r){UserEntity u=users.findByUsernameNorm(r.username().toLowerCase()).filter(x->x.getState()==UserState.active).orElseThrow(()->new BadCredentialsException("invalid credentials"));if(u.getPasswordHash()==null||!encoder.matches(r.password(),u.getPasswordHash()))throw new BadCredentialsException("invalid credentials");String token=jwt.create(u.getId());sessions.save(new SessionEntity(u.getId(),sha(token),r.clientType(),r.deviceLabel(),jwt.expires()));redis.opsForValue().set("presence:"+u.getId(),"online",Duration.ofMinutes(5));return new ApiModels.LoginResponse(token,jwt.expires().getEpochSecond(),new ApiModels.UserView(u.getId(),u.getUsername(),u.getDisplayName()));}
 @Transactional public ApiModels.J2meLogin register(ApiModels.RegisterRequest r){String normalized=r.username().toLowerCase(Locale.ROOT);if(users.findByUsernameNorm(normalized).isPresent())throw new ConflictException("Username is already registered");UserEntity user;try{user=users.saveAndFlush(new UserEntity(r.username(),r.displayName(),encoder.encode(r.password())));}catch(DataIntegrityViolationException e){throw new ConflictException("Username is already registered");}String token=jwt.create(user.getId());sessions.save(new SessionEntity(user.getId(),sha(token),"j2me","Nokia C2-05",jwt.expires()));redis.opsForValue().set("presence:"+user.getId(),"online",Duration.ofMinutes(5));return new ApiModels.J2meLogin(token,jwt.expires().getEpochSecond());}
 private byte[] sha(String v){try{return MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException(e);}}
}
